-- @case 1: [A01] a trailing space after the JSON object: still valid JSON, so the recording is inserted
BEGIN;
DELETE FROM warehouse.vehicle_temperatures;
CREATE TEMP TABLE pp_outcome (outcome text) ON COMMIT DROP;
DO $pp$
BEGIN
  CALL website.record_vehicle_temperature('{"Recordings":[{"type":"Feature","geometry":{"type":"Point","coordinates":[-89.76,50.47]},"properties":{"rego":"WWI-1","sensor":1,"when":"2016-01-01T07:00:00","temp":3.96}}]} '::text);
  INSERT INTO pp_outcome VALUES ('completed');
EXCEPTION
  WHEN SQLSTATE 'P0001' THEN INSERT INTO pp_outcome VALUES ('raised');
END $pp$;
DO $pp$
DECLARE missing bigint; extra bigint;
BEGIN
  SELECT count(*) INTO missing FROM ((SELECT 'completed'::text AS outcome) EXCEPT ALL (SELECT outcome FROM pp_outcome)) AS d;
  SELECT count(*) INTO extra FROM ((SELECT outcome FROM pp_outcome) EXCEPT ALL (SELECT 'completed'::text AS outcome)) AS d;
  IF missing > 0 OR extra > 0 THEN
    RAISE EXCEPTION 'agreed test failed (%): % expected row(s) missing, % unexpected row(s) in the outcome', 'test 01 [A01 a trailing space after the JSON object: still valid JSON, so the recording is inserted', missing, extra;
  END IF;
END $pp$;
